'use client'
import { useState, useRef, useEffect } from 'react'
import { usePathname } from 'next/navigation'
import { Header } from '@/components/Header'
import { Sidebar, RailId } from '@/components/Sidebar'
import { RouteGuard } from '@/components/RouteGuard'
import { getSessionIdentity } from '@/lib/session'

// Analytics module shell. Its pages are the report screens the menu lists
// under Analytics; their routes here are generated by scripts/menu-routes.mjs
// and show the existing screens from their own module folders. Same shell as
// the Configuration layout.
export default function AnalyticsLayout({ children }: { children: React.ReactNode }) {
  const [panelOpen, setPanelOpen] = useState(true)
  const [profileOpen, setProfileOpen] = useState(false)
  const [collapsedSections, setCollapsedSections] = useState<Set<string>>(new Set())
  const [activeRail, setActiveRail] = useState<RailId>('analytics')
  const profileRef = useRef<HTMLDivElement>(null)
  const pathname = usePathname()
  const [displayName, setDisplayName] = useState<string | null>(null)

  // filter(Boolean): the static export (trailingSlash) gives "/x/page/", whose last split part is ''
  const currentPage = pathname.split('/').filter(Boolean).pop() ?? ''

  useEffect(() => {
    const identity = getSessionIdentity()
    if (identity) setDisplayName(identity.displayName)
  }, [])

  useEffect(() => {
    if (typeof window !== 'undefined') window.scrollTo({ top: 0, behavior: 'smooth' })
  }, [pathname])

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (profileRef.current && !profileRef.current.contains(e.target as Node)) {
        setProfileOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  function toggleCollapse(id: string) {
    setCollapsedSections(prev => {
      const s = new Set(prev)
      if (s.has(id)) s.delete(id); else s.add(id)
      return s
    })
  }

  return (
    <>
      <Header
        panelOpen={panelOpen}
        setPanelOpen={setPanelOpen}
        profileOpen={profileOpen}
        setProfileOpen={setProfileOpen}
        profileRef={profileRef}
        displayName={displayName ?? undefined}
      />
      <div className="layout">
        <Sidebar
          panelOpen={panelOpen}
          setPanelOpen={setPanelOpen}
          currentPage={currentPage}
          collapsedSections={collapsedSections}
          toggleCollapse={toggleCollapse}
          activeRail={activeRail}
          setActiveRail={setActiveRail}
        />
        <main className={`main${panelOpen ? ' panel-open' : ''}`}>
          <RouteGuard>{children}</RouteGuard>
        </main>
      </div>
    </>
  )
}
